import os, sys, subprocess, time, signal, shutil
BASE='/tmp/tt'
LOGF='/tmp/w/log.txt'
def fresh(files=('a.txt','b.txt')):
    shutil.rmtree(BASE, ignore_errors=True); os.makedirs(BASE)
    for f in files: open(BASE+'/'+f,'w').write('hi\n')
def log(*s): open(LOGF,'a').write(' '.join(str(x) for x in s)+'\n')
def runh(flags, files, events, util=['echo','RUN'], name='', evgap=0.6, settle=0.5, env=None, stdin_list=True):
    flags = flags if isinstance(flags,list) else [flags]
    e = dict(os.environ); e.update(env or {})
    open('/tmp/tt/list','w').write('\n'.join(files)+'\n')
    out=open('/tmp/tt/out.txt','wb')
    t0=time.time()
    kw = dict(cwd=BASE, env=e)
    if stdin_list: kw['stdin']=open('/tmp/tt/list')
    else: kw['stdin']=open('/dev/null')
    p = subprocess.Popen(['/workspace/executable']+flags+util, stdout=out, stderr=subprocess.STDOUT, **kw)
    time.sleep(0.5)
    for ev in events:
        t=time.time(); ev()
        log('EVT  %-22s dt=%.3f' % (name, t-t0))
        time.sleep(evgap)
    time.sleep(settle)
    if p.poll() is None:
        p.send_signal(signal.SIGINT); time.sleep(0.4)
        if p.poll() is None: p.kill()
    out.close()
    body = open('/tmp/tt/out.txt','rb').read()
    print('--- %-30s rc=%-4s %r' % (name, p.returncode, body))
    return p.returncode, t0
