#include <stdio.h>
#include <sys/inotify.h>
#include <unistd.h>
#include <string.h>
#include <stdlib.h>
#include <fcntl.h>
#include <poll.h>
static const char *maskname(unsigned m){
 static char b[512]; b[0]=0;
 struct {unsigned v;const char*n;} t[]={
 {IN_MODIFY,"MODIFY"},{IN_CREATE,"CREATE"},{IN_DELETE,"DELETE"},{IN_ATTRIB,"ATTRIB"},
 {IN_MOVED_FROM,"MOVED_FROM"},{IN_MOVED_TO,"MOVED_TO"},{IN_OPEN,"OPEN"},{IN_CLOSE_WRITE,"CLOSE_WRITE"},
 {IN_CLOSE_NOWRITE,"CLOSE_NOWRITE"},{IN_DELETE_SELF,"DELETE_SELF"},{IN_MOVE_SELF,"MOVE_SELF"},
 {IN_ISDIR,"ISDIR"},{IN_IGNORED,"IGNORED"},{IN_UNMOUNT,"UNMOUNT"}};
 for(unsigned i=0;i<sizeof(t)/sizeof(t[0]);i++) if(m&t[i].v){ if(b[0]) strcat(b,"|"); strcat(b,t[i].n);}
 return b;
}
int main(int argc, char**argv){
 int fd = inotify_init1(IN_NONBLOCK);
 unsigned mask = (unsigned)strtoul(argv[1],0,0);
 int wd = inotify_add_watch(fd, argv[2], mask);
 printf("wd=%d mask=%x\n", wd, mask);
 fflush(stdout);
 struct pollfd p={fd,POLLIN,0};
 char buf[4096];
 for(int i=0;i<20;i++){
   int n=poll(&p,1,1000);
   if(n<=0){ printf("timeout\n"); fflush(stdout); continue;}
   int len=read(fd,buf,sizeof(buf));
   for(char*p=buf;p<buf+len;){
     struct inotify_event*ev=(struct inotify_event*)p;
     printf("event mask=%s(%x) cookie=%u name=%s\n", maskname(ev->mask), ev->mask, ev->cookie, ev->len?ev->name:"");
     fflush(stdout);
     p+=sizeof(struct inotify_event)+ev->len;
   }
 }
 return 0;
}
