        return -1;
    }
    return 0;
}

static void read_file_list(void)
{
    char line[PATH_MAX * 2];
    int i;
    while (fgets(line, sizeof(line), stdin) != NULL) {
        size_t len = strlen(line);
        struct stat st;
        const char *name;
        while (len > 0 && line[len-1] == '\n') line[--len] = 0;
        if (len == 0) continue;
        name = line;
        if (stat(name, &st) == -1) {
            fprintf(stderr, "%s: unable to stat '%s'\n", argv0, name);
            continue;
