        if (S_ISDIR(st.st_mode)) {
            int di;
            if ((di = dirindex(name)) >= 0) continue;
            watches = realloc(watches, (nwatch + 1) * sizeof(struct watch));
            memset(&watches[nwatch], 0, sizeof(struct watch));
            watches[nwatch].path = xstrdup(name);
            watches[nwatch].type = F_DIR;
            watches[nwatch].dir_listed = 1;
            watches[nwatch].count = count_entries(name, !(d_count > 1));
            nwatch++;
        } else if (S_ISREG(st.st_mode)) {
            char dir[PATH_MAX + 1];
            char *slash;
            int di = -1;
            watches = realloc(watches, (nwatch + 1) * sizeof(struct watch));
            memset(&watches[nwatch], 0, sizeof(struct watch));
            watches[nwatch].path = xstrdup(name);
            watches[nwatch].type = F_FILE;
            nwatch++;
