                snprintf(dir, sizeof(dir), "%s", name);
                slash = strrchr(dir, '/');
                if (slash != NULL) {
                    if (slash == dir) dir[1] = 0; else *slash = 0;
                    if ((di = dirindex(dir)) < 0) {
                        struct stat dst;
                        if (stat(dir, &dst) == 0 && S_ISDIR(dst.st_mode)) {
                            watches = realloc(watches, (nwatch + 1) * sizeof(struct watch));
                            memset(&watches[nwatch], 0, sizeof(struct watch));
                            watches[nwatch].path = xstrdup(dir);
                            watches[nwatch].type = F_DIR;
                            watches[nwatch].count = count_entries(dir, !(d_count > 1));
                            di = nwatch;
                            nwatch++;
                        }
                    }
                } else {
                    /* no slash: relative to the current directory */
                    if ((di = dirindex(".")) < 0) {
                        struct stat dst;
                        if (stat(".", &dst) == 0 && S_ISDIR(dst.st_mode)) {
                            watches = realloc(watches, (nwatch + 1) * sizeof(struct watch));
                            memset(&watches[nwatch], 0, sizeof(struct watch));
                            watches[nwatch].path = xstrdup(".");
                            watches[nwatch].type = F_DIR;
                            watches[nwatch].count = count_entries(".", !(d_count > 1));
                            di = nwatch;
                            nwatch++;
                        }
                    }
                }
            }
            watches[nwatch-1].dir_of = di;
        }
        /* anything else (symlinks, fifos, devices) is silently skipped */
    }
    for (i = 0; i < nwatch; i++) {
        if (stat(watches[i].path, &st) == 0) {
            watches[i].mode = st.st_mode;
            watches[i].dev = st.st_dev;
