    run_needed = 1;
    if (debounce_until == 0) debounce_until = now_ns() + DEBOUNCE_NS;
}

static void dir_event(struct watch *w, unsigned mask, unsigned cookie, int is_move)
{
    long long now = now_ns();
    int i, paired = 0;
    if (dir_settle_until > now) {
        /* already settling: extend the window */
        dir_settle_until = now + SETTLE_NS;
        dir_check_pending = 1;
        return;
    }
    if (is_move) {
        for (i = 0; i < npairs; i++) {
            if (pairs[i].cookie == cookie) { pairs[i].mask |= mask; paired = 1; break; }
        }
        if (paired) {
            /* the entry was renamed within the directory: not an alteration */
            if (((pairs[i].mask & IN_MOVED_FROM) && (pairs[i].mask & IN_MOVED_TO))) {
                pairs[i] = pairs[npairs-1]; npairs--;
                return;
            }
            i = npairs;
        }
        if (npairs < MAXPAIRS) {
            pairs[npairs].cookie = cookie;
            pairs[npairs].mask = mask;
            npairs++;
        }
        dir_check_pending = 1;
        if (dir_pair_until == 0) dir_pair_until = now + MOVEWAIT_NS;
        return;
    }
    /* create or delete */
    dir_check_pending = 1;
    dir_settle_until = now + SETTLE_NS;
}

