{
    fprintf(stderr, "%s: directory altered\n", argv0);
    fflush(stderr);
    exit(2);
}

/* attempt to re-establish a watch on a file which disappeared; returns 0 on
 * success, -1 if the file could not be found */
static int reestablish(struct watch *w)
{
    int i;
    struct stat st;
    for (i = 0; i < RETRIES; i++) {
        if (nanosleep_retry(RETRY_NS) != 0) { /* ignore */ }
        if (stat(w->path, &st) == 0 && S_ISREG(st.st_mode)) {
