static int reestablish(struct watch *w)
{
    int i;
    struct stat st;
    for (i = 0; i < RETRIES; i++) {
        nap(RETRY_NS);
        if (stat(w->path, &st) == 0 && S_ISREG(st.st_mode)) {
            w->mode = st.st_mode;
            w->dev = st.st_dev;
            w->ino = st.st_ino;
            if (add_watch(w) >= 0) {
                note_run();
                return 0;
            }
            fprintf(stderr, "%s: failed to register VNODE event: %s\n", argv0, strerror(errno));
            return -1;
        }
    }
    return -1;
}

static void check_missing_files(void)
{
    int i;
    for (i = 0; i < nwatch; i++) {
        struct stat st;
        if (watches[i].type != F_FILE) continue;
        if (!watches[i].missing) continue;
        if (reestablish(&watches[i]) == -1) {
            int fd = open(watches[i].path, O_RDONLY);
            if (fd == -1) {
                fprintf(stderr, "%s: cannot open '%s': %s\n", argv0, watches[i].path, strerror(errno));
                fflush(stderr);
                exit(1);
            }
            close(fd);
        }
    }
}

static void check_directories(struct watch *w)
{
    int i, n;
    for (i = 0; i < nwatch; i++) {
        if (watches[i].type != F_DIR) continue;
        if (w != NULL && watches[i].wd != w->wd) continue;
        n = count_entries(watches[i].path, !(d_count_two));
        if (n < 0) {
            fprintf(stderr, "%s: unable to open directory: '%s'\n", argv0, watches[i].path);
            fflush(stderr);
            exit(1);
        }
        if (n != watches[i].count) {
            trace_event(0, 1, NOTE_WRITE, &watches[i]);
            run_needed = 0;
            debounce_until = 0;
            run_utility(g_utility, g_nutility);
            if (IS_X()) {
                int ok = reap_child(1);
                if (ok) report_status(child_signal(), WIFEXITED(child_status) ? WEXITSTATUS(child_status) : 0);
            }
            dir_altered();
        }
    }
}

