        dir_settle_until = now + SETTLE_NS;
        dir_pending = 1;
        return;
    }
    if (is_move) {
        for (i = 0; i < npairs; i++) {
            if (pairs[i].cookie == cookie) break;
        }
        if (i < npairs) {
            pairs[i].mask |= mask;
