/* ------------------------------------------------------- main loop ----- */

static char **g_utility;
static int g_nutility;
static int first_run_done = 0;

static void cleanup(void)
{
    if (tty_restore && tty_fd != -1) tcsetattr(tty_fd, TCSANOW, &tty_save);
    if (status_fd != -1) close(status_fd);
    fflush(stdout);
    fflush(stderr);
}

static void child_finished(void)
{
    if (IS_X()) report_status(child_signal(), WIFEXITED(child_status) ? WEXITSTATUS(child_status) : 0);
    if (IS_Z()) {
        cleanup();
        exit(child_code());
    }
    if (!IS_A()) {
        post_child_until = now_ns() + DEBOUNCE_NS;
        consolidate = 1;
    }
    run_needed = 0;
    debounce_until = 0;
}

static void do_run(void)
{
    int ok;
    if (IS_R() && child_running) {
        /* restart the persistent child process */
        killpg(child_pid, restart_sig);
        while (!reap_child(1)) ;
    }
    run_utility(g_utility, g_nutility);
    trigger_path = NULL;
    run_needed = 0;
    (void)ok;
}

static void do_run_and_wait(void)
{
    run_utility(g_utility, g_nutility);
    while (!reap_child(1)) ;
    child_finished();
    trigger_path = NULL;
    run_needed = 0;
}

static void handle_inotify(void)
{
    char buf[4096];
    ssize_t len;
    while ((len = read(ifd, buf, sizeof(buf))) > 0) {
        char *p = buf;
        char *end = buf + len;
        int total = 0, idx = 0;
        struct inotify_event *ev;
        for (p = buf; p < end; ) {
            ev = (struct inotify_event *)p;
            p += sizeof(struct inotify_event) + ev->len;
            total++;
        }
        idx = 0;
        for (p = buf; p < end; ) {
            struct watch *w = NULL;
            int i;
            ev = (struct inotify_event *)p;
            p += sizeof(struct inotify_event) + ev->len;
            for (i = 0; i < nwatch; i++) {
                if (watches[i].wd == ev->wd) { w = &watches[i]; break; }
            }
            idx++;
            if (w == NULL) continue;
            if (consolidate) continue;
            if (post_child_until > now_ns() && !IS_A()) continue;
            if (w->type == F_FILE) {
                if (ev->mask & IN_MODIFY) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_WRITE;
                    w->trace_valid = 1;
                    set_trigger(w);
                    note_run();
                } else if (ev->mask & IN_ATTRIB) {
                    struct stat st;
                    if (stat(w->path, &st) == 0 && st.st_mode != w->mode) {
                        w->mode = st.st_mode;
                        w->trace_idx = idx - 1;
                        w->trace_total = total;
                        w->trace_flags = NOTE_ATTRIB;
                        w->trace_valid = 1;
                        set_trigger(w);
                        note_run();
                    }
                } else if (ev->mask & (IN_DELETE_SELF | IN_MOVE_SELF)) {
                    w->missing = 1;
                    w->wd = -1;
                    /* handled at the next opportunity */
                    check_missing_files();
                }
            } else {
                if (ev->mask & (IN_MOVED_FROM | IN_MOVED_TO)) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_RENAME;
                    w->trace_valid = 1;
                    dir_event(w, ev->mask, ev->cookie, 1);
                } else if (ev->mask & (IN_CREATE | IN_DELETE)) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_WRITE;
                    w->trace_valid = 1;
                    dir_event(w, ev->mask, 0, 0);
                } else if (ev->mask & IN_DELETE_SELF) {
                    fprintf(stderr, "%s: unable to open directory: '%s'\n", argv0, w->path);
                    fflush(stderr);
                    cleanup();
                    exit(1);
                }
            }
        }
    }
}

static void handle_tty(void)
{
    char ch;
    ssize_t n;
    while ((n = read(tty_fd, &ch, 1)) > 0) {
        if (ch == ' ') {
            set_trigger(NULL);
            note_run();
        } else if (ch == 'q') {
            cleanup();
            exit(0);
        }
    }
}

static void main_loop(void)
{
    struct pollfd pfd[2];
    int npfd;
    int first = !IS_P();

    if (first) {
        run_utility(g_utility, g_nutility);
        while (!reap_child(1)) ;
