    trigger_path = NULL;
    run_needed = 0;
}

static void handle_inotify(void)
{
    char buf[4096];
    ssize_t len;
    while ((len = read(ifd, buf, sizeof(buf))) > 0) {
        char *p = buf;
        char *end = buf + len;
        int total = 0, idx = 0;
        struct inotify_event *ev;
        for (p = buf; p < end; ) {
            ev = (struct inotify_event *)p;
            p += sizeof(struct inotify_event) + ev->len;
            total++;
        }
        idx = 0;
        for (p = buf; p < end; ) {
            struct watch *w = NULL;
            int i;
            ev = (struct inotify_event *)p;
            p += sizeof(struct inotify_event) + ev->len;
            for (i = 0; i < nwatch; i++) {
                if (watches[i].wd == ev->wd) { w = &watches[i]; break; }
            }
            idx++;
            if (w == NULL) continue;
            if (consolidate) continue;
            if (post_child_until > now_ns() && !IS_A()) continue;
            if (w->type == F_FILE) {
                if (ev->mask & IN_MODIFY) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_WRITE;
                    w->trace_valid = 1;
                    set_trigger(w);
                    note_run();
                } else if (ev->mask & IN_ATTRIB) {
                    struct stat st;
                    if (stat(w->path, &st) == 0 && st.st_mode != w->mode) {
                        w->mode = st.st_mode;
                        w->trace_idx = idx - 1;
                        w->trace_total = total;
                        w->trace_flags = NOTE_ATTRIB;
                        w->trace_valid = 1;
                        set_trigger(w);
                        note_run();
                    }
