{
    char ch;
    ssize_t n;
    while ((n = read(tty_fd, &ch, 1)) > 0) {
        if (ch == ' ') {
            set_trigger(NULL);
            note_run();
        } else if (ch == 'q') {
            cleanup();
            exit(0);
        }
    }
}

