        npfd = 0;
        pfd[npfd].fd = ifd;
        pfd[npfd].events = POLLIN;
        pfd[npfd].revents = 0;
        npfd++;
        if (!IS_N() && tty_fd != -1 && !child_running) {
            pfd[npfd].fd = tty_fd;
            pfd[npfd].events = POLLIN;
            pfd[npfd].revents = 0;
            npfd++;
