actions.command:
cat > /workspace/src/entr.c <<'CEOF'
/*
 * entr - Event Notify Test Runner.
 *
 * Reimplementation of the "entr" utility for Linux, built on inotify.  The
 * behaviour of the reference implementation (release 5.7) was reproduced
 * from observation of the reference binary.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <poll.h>
#include <dirent.h>
#include <time.h>
#include <limits.h>
#include <sys/inotify.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <termios.h>

#define ENTR_RELEASE "5.7"

#define OPT_A 0x001     /* -a do not consolidate events */
#define OPT_C 0x002     /* -c clear screen */
#define OPT_D 0x004     /* -d track parent directory */
#define OPT_N 0x008     /* -n non interactive */
#define OPT_P 0x010     /* -p postpone first execution */
#define OPT_R 0x020     /* -r reload persistent child */
#define OPT_S 0x040     /* -s evaluate using a shell */
#define OPT_X 0x080     /* -x format exit status */
#define OPT_Z 0x100     /* -z exit after utility completes */

#define IS_A() (options & OPT_A)
#define IS_C() (options & OPT_C)
#define IS_D() (options & OPT_D)
#define IS_N() (options & OPT_N)
#define IS_P() (options & OPT_P)
#define IS_R() (options & OPT_R)
#define IS_S() (options & OPT_S)
#define IS_X() (options & OPT_X)
#define IS_Z() (options & OPT_Z)

#define F_DIR   1
#define F_FILE  2

#define MASK_FILE  (IN_MODIFY | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF)
#define MASK_DIR   (IN_MODIFY | IN_ATTRIB | IN_CREATE | IN_DELETE | \
                    IN_MOVED_FROM | IN_MOVED_TO | IN_DELETE_SELF | IN_MOVE_SELF)

/* kqueue note flags, used by the event trace */
#define NOTE_DELETE 0x01
#define NOTE_WRITE  0x02
#define NOTE_EXTEND 0x04
#define NOTE_ATTRIB 0x08
#define NOTE_LINK   0x10
#define NOTE_RENAME 0x20
#define NOTE_REVOKE 0x40

#define DEBOUNCE_NS   50000000LL     /* 50 ms consolidation window */
#define SETTLE_NS     500000000LL    /* 500 ms directory settle window */
#define MOVEWAIT_NS   50000000LL     /* 50 ms rename pairing window */
#define RETRIES       10
#define RETRY_NS      100000000LL    /* 100 ms between attempts */

struct watch {
    char   *path;
    int     wd;
    int     type;           /* F_DIR or F_FILE */
    int     missing;
    mode_t  mode;
    dev_t   dev;
    ino_t   ino;
    int     count;          /* directory baseline entry count */
    int     trace_idx;
    int     trace_total;
    unsigned trace_flags;
    int     trace_valid;
};

static struct watch *watches;
static int  nwatch = 0;
static int  wcap = 0;
static int  ifd = -1;
static const char *argv0 = "entr";
static int  options = 0;
static int  clear_count = 0;
static int  x_count = 0;
static int  d_count = 0;
static int  restart_sig = SIGTERM;
static int  tty_fd = -1;
static struct termios tty_save;
static int  tty_restore = 0;
static int  status_fd = -1;
static char *status_script = NULL;
static volatile sig_atomic_t got_sigint = 0;
static pid_t child_pid = 0;
static int  child_running = 0;
static int  child_status = 0;
static const char *utility_name = "entr";
static char *trigger_path = NULL;
static int  trace = 0;
static int  workaround = 0;
static int  follow_symlink = 0;

static char **g_utility;
static int  g_nutility;

static void die(const char *msg)
{
    fprintf(stderr, "%s: %s\n", argv0, msg);
    exit(1);
}

static void *xmalloc(size_t n)
{
    void *p = malloc(n);
    if (p == NULL) die("out of memory");
    return p;
}

static void *xrealloc(void *p, size_t n)
{
    p = realloc(p, n);
    if (p == NULL) die("out of memory");
    return p;
}

static char *xstrdup(const char *s)
{
    char *p = xmalloc(strlen(s) + 1);
    strcpy(p, s);
    return p;
}

static const char *progname(const char *path)
{
    const char *p = strrchr(path, '/');
    return p ? p + 1 : path;
}

/* ------------------------------------------------------------ usage --- */

static void usage_summary(void)
{
    printf("release: %s\n", ENTR_RELEASE);
    printf("usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    printf("summary:\n");
    printf("    -a  Do not consolidate events\n");
    printf("    -c  Clear screen before execution\n");
    printf("    -d  Track files added or removed from directories\n");
    printf("    -n  Non-interactive mode\n");
    printf("    -p  Wait for first event\n");
    printf("    -r  Run as a background process, use signal to restart\n");
    printf("    -s  Evaluate using a shell\n");
    printf("    -x  Format exit status\n");
    printf("    -z  Exit after the utility completes\n");
    printf("docs:\n");
    printf("    man entr\n");
    exit(1);
}

static void usage_short(void)
{
    printf("release: %s\n", ENTR_RELEASE);
    printf("usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    printf("hint: use -h to display option summary\n");
    exit(1);
}

/* ---------------------------------------------------------- helpers --- */

static long long now_ns(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

static void nap(long long ns)
{
    struct timespec ts;
    ts.tv_sec = ns / 1000000000LL;
    ts.tv_nsec = ns % 1000000000LL;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) ;
}

static int ms_until(long long deadline)
{
    long long d = (deadline - now_ns()) / 1000000LL;
    if (d < 0) d = 0;
    if (d > 3600000) d = 3600000;
    return (int)d;
}

static int hidden(const char *name)
{
    return name[0] == '.';
}

/* stat a path honouring ENTR_FOLLOW_SYMLINK */
static int dostat(const char *path, struct stat *st)
{
    if (follow_symlink) return stat(path, st);
    return lstat(path, st);
}

static int count_entries(const char *dir, int skip_hidden)
{
    DIR *d;
    struct dirent *e;
    int n = 0;
    if ((d = opendir(dir)) == NULL) return -1;
    while ((e = readdir(d)) != NULL) {
        if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;
        if (skip_hidden && hidden(e->d_name)) continue;
        n++;
    }
    closedir(d);
    return n;
}

static int same_path(const char *a, const char *b)
{
    char ca[PATH_MAX + 2], cb[PATH_MAX + 2];
    int i, j;
    for (i = 0, j = 0; a[i] && j < PATH_MAX; i++) {
        if (a[i] == '/' && j > 0 && ca[j-1] == '/') continue;
        ca[j++] = a[i];
    }
    ca[j] = 0;
    for (i = 0, j = 0; b[i] && j < PATH_MAX; i++) {
        if (b[i] == '/' && j > 0 && cb[j-1] == '/') continue;
        cb[j++] = b[i];
    }
    cb[j] = 0;
    return strcmp(ca, cb) == 0;
}

static int dirindex(const char *path)
{
    int i;
    for (i = 0; i < nwatch; i++)
        if (watches[i].type == F_DIR && same_path(watches[i].path, path))
            return i;
    return -1;
}

static struct watch *new_watch(void)
{
    if (nwatch == wcap) {
        wcap = wcap ? wcap * 2 : 64;
        watches = xrealloc(watches, wcap * sizeof(struct watch));
    }
    memset(&watches[nwatch], 0, sizeof(struct watch));
    return &watches[nwatch++];
}

static int add_watch(struct watch *w)
{
    int mask = (w->type == F_DIR) ? MASK_DIR : MASK_FILE;
    w->wd = inotify_add_watch(ifd, w->path, mask);
    w->missing = (w->wd < 0);
    return w->wd;
}

static void add_dir_watch(const char *path)
{
    struct stat st;
    if (dirindex(path) >= 0) return;
    if (dostat(path, &st) == -1 || !S_ISDIR(st.st_mode)) return;
    {
        struct watch *w = new_watch();
        w->path = xstrdup(path);
        w->type = F_DIR;
        w->count = count_entries(path, !(d_count > 1));
    }
}

/* --------------------------------------------------------- file list --- */

static void read_file_list(void)
{
    static char line[PATH_MAX * 2];
    struct stat st;
    int i;
    while (fgets(line, sizeof(line), stdin) != NULL) {
        size_t len = strlen(line);
        while (len > 0 && line[len-1] == '\n') line[--len] = 0;
        if (len == 0) continue;
        if (dostat(line, &st) == -1) {
            fprintf(stderr, "%s: unable to stat '%s'\n", argv0, line);
            continue;
        }
        if (S_ISDIR(st.st_mode)) {
            if (dirindex(line) >= 0) continue;
            {
                struct watch *w = new_watch();
                w->path = xstrdup(line);
                w->type = F_DIR;
                w->count = count_entries(line, !(d_count > 1));
            }
        } else if (S_ISREG(st.st_mode)) {
            char dir[PATH_MAX + 2];
            char *slash;
            struct watch *w;
            int di;
            w = new_watch();
            w->path = xstrdup(line);
            w->type = F_FILE;
            di = -1;
            if (d_count > 0) {
                snprintf(dir, sizeof(dir), "%s", line);
                slash = strrchr(dir, '/');
                if (slash == NULL) {
                    add_dir_watch(".");
                } else if (slash == dir) {
                    dir[1] = 0;
                    add_dir_watch(dir);
                } else {
                    *slash = 0;
                    add_dir_watch(dir);
                }
                di = dirindex(w->path);
            }
            (void)di;
        }
        /* symlinks, fifos, devices and sockets are silently ignored */
    }
    for (i = 0; i < nwatch; i++) {
        if (dostat(watches[i].path, &st) == 0) {
            watches[i].mode = st.st_mode;
            watches[i].dev = st.st_dev;
            watches[i].ino = st.st_ino;
        }
    }
}

static int has_regular(void)
{
    int i;
    for (i = 0; i < nwatch; i++) if (watches[i].type == F_FILE) return 1;
    return 0;
}

/* -------------------------------------------------------------- tty ---- */

static void setup_tty(void)
{
    struct termios t;
    if (isatty(STDIN_FILENO)) tty_fd = STDIN_FILENO;
    else                      tty_fd = open("/dev/tty", O_RDWR);
    if (tty_fd == -1 || tcgetattr(tty_fd, &t) == -1) {
        fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", argv0);
        exit(1);
    }
    tty_save = t;
    t.c_lflag &= ~(tcflag_t)(ICANON | ECHO);
    t.c_cc[VMIN] = 1;
    t.c_cc[VTIME] = 0;
    tcsetattr(tty_fd, TCSANOW, &t);
    tty_restore = 1;
}

/* ------------------------------------------------------- status (-x) --- */

static void setup_status(void)
{
    char home[PATH_MAX + 64];
    char *env;
    int pipefd[2];

    if ((env = getenv("ENTR_STATUS_SCRIPT")) != NULL && *env != 0) {
        status_script = xstrdup(env);
    } else if ((env = getenv("HOME")) != NULL && *env != 0) {
        snprintf(home, sizeof(home), "%s/.entr/status.awk", env);
        status_script = xstrdup(home);
    } else {
        status_script = xstrdup(".entr/status.awk");
    }
    if (access(status_script, F_OK) == -1) {
        static const char *example[] = {
            "# http://eradman.com/entrproject/status-filters.html\n",
            "/^signal/ { print $3, \"terminated by signal\", $2; }\n",
            "/^exit/ { print $3, \"returned exit code\", $2; }\n",
            NULL
        };
        char *slash = strrchr(status_script, '/');
        int fd, i;
        if (slash != NULL) {
            *slash = 0;
            mkdir(status_script, 0750);
            *slash = '/';
        }
        fd = open(status_script, O_WRONLY | O_CREAT | O_EXCL, 0640);
        if (fd != -1) {
            for (i = 0; example[i] != NULL; i++) write(fd, example[i], strlen(example[i]));
            close(fd);
            fprintf(stderr, "%s: created '%s'\n", argv0, status_script);
        }
    }
    if (pipe(pipefd) == -1) return;
    if (fork() == 0) {
        int i;
        dup2(pipefd[0], STDIN_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);
        for (i = 3; i < 64; i++) close(i);
        if (x_count > 1)
            execlp("awk", "awk", "-F", "|", "-f", status_script, (char *)NULL);
        else
            execlp("awk", "awk", "-F", "|", "-f", status_script, "-S", (char *)NULL);
        _exit(1);
    }
    close(pipefd[0]);
    status_fd = pipefd[1];
}

static void report_status(int signo, int code)
{
    char buf[256];
    int n;
    if (status_fd == -1) return;
    if (signo) n = snprintf(buf, sizeof(buf), "signal|%d|%s\n", signo, utility_name);
    else       n = snprintf(buf, sizeof(buf), "exit|%d|%s\n", code, utility_name);
    if (write(status_fd, buf, n) < 0) {
        fprintf(stderr, "%s: status process terminated\n", argv0);
        fflush(stderr);
        _exit(0);
    }
}

/* ---------------------------------------------------------- utility ---- */

static void clear_screen(void)
{
    if (clear_count > 0) fputs("\033[2J", stdout);
    if (clear_count > 1) fputs("\033[3J", stdout);
    fputs("\033[H", stdout);
    fflush(stdout);
}

static void run_utility(void)
{
    pid_t pid;
    int i;
    char **av;
    if (IS_C()) clear_screen();
    fflush(stdout);
    fflush(stderr);
    pid = fork();
    if (pid == -1) {
        fprintf(stderr, "%s: fork: %s\n", argv0, strerror(errno));
        return;
    }
    if (pid == 0) {
        av = xmalloc((g_nutility + 2) * sizeof(char *));
        for (i = 0; i < g_nutility; i++) av[i] = g_utility[i];
        av[g_nutility] = NULL;
        setpgid(0, 0);
        if (tty_fd != -1 && !IS_R()) tcsetpgrp(tty_fd, getpgid(0));
        execvp(av[0], av);
        fprintf(stderr, "%s: exec %s: %s\n", argv0, av[0], strerror(errno));
        _exit(1);
    }
    child_pid = pid;
    child_running = 1;
}

static int reap_child(int block)
{
    int status = 0;
    pid_t pid;
    if (!child_running) return 0;
    do {
        pid = waitpid(child_pid, &status, block ? 0 : WNOHANG);
    } while (pid == -1 && errno == EINTR);
    if (pid != child_pid) return 0;
    child_running = 0;
    child_status = status;
    child_pid = 0;
    if (tty_fd != -1 && !IS_R()) tcsetpgrp(tty_fd, getpgid(0));
    return 1;
}

static int child_signal(void)
{
    if (WIFSIGNALED(child_status)) return WTERMSIG(child_status);
    return 0;
}

static int child_code(void)
{
    if (WIFEXITED(child_status)) return WEXITSTATUS(child_status);
    if (WIFSIGNALED(child_status)) return WTERMSIG(child_status) + 128;
    return 0;
}

/* ------------------------------------------------- trace/dir state ----- */

static void trace_event(struct watch *w)
{
    fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n", w->trace_idx, w->trace_total,
            w->trace_flags, (w->type == F_DIR) ? 'd' : 'r', (unsigned)w->mode, w->path);
    fflush(stderr);
}

#define MAXPAIRS 64
struct pair { long long cookie; unsigned mask; };
static struct pair pairs[MAXPAIRS];
static int npairs = 0;
static int dir_pending = 0;
static long long dir_settle_until = 0;
static long long dir_pair_until = 0;
static int run_needed = 0;
static long long debounce_until = 0;
static long long post_child_until = 0;
static int consolidate = 0;

static void note_run(void)
{
    run_needed = 1;
    if (debounce_until == 0) debounce_until = now_ns() + DEBOUNCE_NS;
}

static void set_trigger_file(struct watch *w)
{
    char buf[PATH_MAX + 2];
    if (w != NULL && realpath(w->path, buf) != NULL) {
        if (trigger_path != NULL) free(trigger_path);
        trigger_path = xstrdup(buf);
    }
}

static void dir_event(struct watch *w, unsigned mask, unsigned cookie, int is_move)
{
    long long now = now_ns();
    int i;
    if (dir_settle_until > now) {
        dir_settle_until = now + SETTLE_NS;
        dir_pending = 1;
        return;
    }
    if (is_move) {
        for (i = 0; i < npairs; i++) if (pairs[i].cookie == cookie) break;
        if (i < npairs) {
            pairs[i].mask |= mask;
            if ((pairs[i].mask & IN_MOVED_FROM) && (pairs[i].mask & IN_MOVED_TO)) {
                pairs[i] = pairs[npairs-1];
                npairs--;
                return;
            }
        } else if (npairs < MAXPAIRS) {
            pairs[npairs].cookie = cookie;
            pairs[npairs].mask = mask;
            npairs++;
        }
        dir_pending = 1;
        if (dir_pair_until == 0) dir_pair_until = now + MOVEWAIT_NS;
        return;
    }
    dir_pending = 1;
    dir_settle_until = now + SETTLE_NS;
}

static int resolve_pairs(void)
{
    int i, need = 0;
    for (i = 0; i < npairs; i++)
        if (!((pairs[i].mask & IN_MOVED_FROM) && (pairs[i].mask & IN_MOVED_TO))) need = 1;
    npairs = 0;
    dir_pair_until = 0;
    if (need) dir_settle_until = now_ns() + SETTLE_NS;
    return need;
}

/* ------------------------------------------------------ dir checks ----- */

static void dir_altered(void)
{
    fprintf(stderr, "%s: directory altered\n", argv0);
    fflush(stderr);
    exit(2);
}

static int reestablish(struct watch *w)
{
    int i;
    struct stat st;
    for (i = 0; i < RETRIES; i++) {
        nap(RETRY_NS);
        if (dostat(w->path, &st) == 0 && S_ISREG(st.st_mode)) {
            w->mode = st.st_mode;
            w->dev = st.st_dev;
            w->ino = st.st_ino;
            if (add_watch(w) >= 0) {
                note_run();
                return 0;
            }
            fprintf(stderr, "%s: failed to register VNODE event: %s\n", argv0, strerror(errno));
            return -1;
        }
    }
    return -1;
}

static void check_missing_files(void)
{
    int i;
    for (i = 0; i < nwatch; i++) {
        struct stat st;
        if (watches[i].type != F_FILE) continue;
        if (!watches[i].missing) continue;
        if (reestablish(&watches[i]) == -1) {
            int fd = open(watches[i].path, O_RDONLY);
            if (fd == -1) {
                fprintf(stderr, "%s: cannot open '%s': %s\n", argv0, watches[i].path, strerror(errno));
                fflush(stderr);
                exit(1);
            }
            close(fd);
        }
    }
}

static void check_directories(void)
{
    int i, n;
    for (i = 0; i < nwatch; i++) {
        if (watches[i].type != F_DIR) continue;
        n = count_entries(watches[i].path, !(d_count > 1));
        if (n < 0) {
            fprintf(stderr, "%s: unable to open directory: '%s'\n", argv0, watches[i].path);
            fflush(stderr);
            exit(1);
        }
        if (n != watches[i].count) {
            if (watches[i].trace_valid) trace_event(&watches[i]);
            run_needed = 0;
            debounce_until = 0;
            run_utility();
            if (IS_X()) {
                while (!reap_child(1)) ;
                report_status(child_signal(), WIFEXITED(child_status) ? WEXITSTATUS(child_status) : 0);
            }
            dir_altered();
        }
    }
}

/* ----------------------------------------------------- event input ----- */

static void handle_inotify(void)
{
    static char buf[4096];
    ssize_t len;
    while ((len = read(ifd, buf, sizeof(buf))) > 0) {
        char *p, *end;
        int total = 0, idx = 0;
        end = buf + len;
        for (p = buf; p < end; ) {
            struct inotify_event *ev = (struct inotify_event *)p;
            p += sizeof(struct inotify_event) + ev->len;
            total++;
        }
        idx = 0;
        for (p = buf; p < end; ) {
            struct inotify_event *ev = (struct inotify_event *)p;
            struct watch *w = NULL;
            int i;
            p += sizeof(struct inotify_event) + ev->len;
            idx++;
            for (i = 0; i < nwatch; i++) if (watches[i].wd == ev->wd) { w = &watches[i]; break; }
            if (w == NULL) continue;
            if (consolidate) continue;
            if (!IS_A() && post_child_until > now_ns()) continue;
            if (w->type == F_FILE) {
                if (ev->mask & IN_MODIFY) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_WRITE;
                    w->trace_valid = 1;
                    set_trigger_file(w);
                    note_run();
                } else if (ev->mask & IN_ATTRIB) {
                    struct stat st;
                    if (dostat(w->path, &st) == 0 && st.st_mode != w->mode) {
                        w->mode = st.st_mode;
                        w->trace_idx = idx - 1;
                        w->trace_total = total;
                        w->trace_flags = NOTE_ATTRIB;
                        w->trace_valid = 1;
                        set_trigger_file(w);
                        note_run();
                    }
                } else if (ev->mask & (IN_DELETE_SELF | IN_MOVE_SELF)) {
                    w->missing = 1;
                    w->wd = -1;
                    if (!dir_pending) check_missing_files();
                }
            } else {
                if (ev->mask & (IN_MOVED_FROM | IN_MOVED_TO)) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_RENAME;
                    w->trace_valid = 1;
                    dir_event(w, ev->mask, ev->cookie, 1);
                } else if (ev->mask & (IN_CREATE | IN_DELETE)) {
                    w->trace_idx = idx - 1;
                    w->trace_total = total;
                    w->trace_flags = NOTE_WRITE;
                    w->trace_valid = 1;
                    dir_event(w, ev->mask, 0, 0);
                } else if (ev->mask & IN_DELETE_SELF) {
                    fprintf(stderr, "%s: unable to open directory: '%s'\n", argv0, w->path);
                    fflush(stderr);
                    cleanup();
                    exit(1);
                }
            }
        }
    }
}

static void handle_tty(void)
{
    char ch;
    ssize_t n;
    while ((n = read(tty_fd, &ch, 1)) > 0) {
        if (ch == ' ') {
            note_run();
        } else if (ch == 'q') {
            cleanup();
            exit(0);
        }
    }
}

/* ----------------------------------------------------- child exit ------ */

static void child_finished(void)
{
    if (IS_X()) report_status(child_signal(), WIFEXITED(child_status) ? WEXITSTATUS(child_status) : 0);
    if (IS_Z()) {
        cleanup();
        exit(child_code());
    }
    if (!IS_A()) {
        post_child_until = now_ns() + DEBOUNCE_NS;
        consolidate = 1;
    }
    run_needed = 0;
    debounce_until = 0;
}

static void do_run(void)
{
    if (IS_R() && child_running) {
        killpg(child_pid, restart_sig);
        while (!reap_child(1)) ;
    }
    run_utility();
    if (trigger_path != NULL) { free(trigger_path); trigger_path = NULL; }
    run_needed = 0;
    /* with -z the child is awaited immediately */
    if (IS_Z()) {
        while (!reap_child(1)) ;
        child_finished();
    }
}

/* ----------------------------------------------------- main loop ------- */

static void cleanup(void)
{
    if (tty_restore && tty_fd != -1) tcsetattr(tty_fd, TCSANOW, &tty_save);
    if (status_fd != -1) close(status_fd);
    fflush(stdout);
    fflush(stderr);
}

static void main_loop(void)
{
    struct pollfd pfd[2];
    int npfd;

    if (!IS_P()) {
        run_utility();
        while (!reap_child(1)) ;
        child_finished();
    }

    for (;;) {
        long long now;
        int timeout, nready;

        if (got_sigint) {
            got_sigint = 0;
            if (child_running) {
                if (IS_R()) killpg(child_pid, SIGINT);
            } else {
                cleanup();
                exit(0);
            }
        }
        now = now_ns();
        if (child_running && reap_child(0)) child_finished();
        if (dir_pair_until && now >= dir_pair_until) resolve_pairs();
        if (dir_settle_until && now >= dir_settle_until) {
            dir_settle_until = 0;
            dir_pending = 0;
            check_missing_files();
            check_directories();
            if (run_needed) debounce_until = now_ns() + DEBOUNCE_NS;
        }
        if (debounce_until && now >= debounce_until) {
            if (!child_running && dir_settle_until == 0 && dir_pair_until == 0 &&
                (!post_child_until || post_child_until < now)) {
                debounce_until = 0;
                if (run_needed) {
                    int i;
                    if (trace) {
                        for (i = 0; i < nwatch; i++) {
                            if (watches[i].trace_valid) {
                                trace_event(&watches[i]);
                                watches[i].trace_valid = 0;
                            }
                        }
                    }
                    do_run();
                }
            }
        }
        if (post_child_until && now >= post_child_until) {
            post_child_until = 0;
            consolidate = 0;
        }

        npfd = 0;
        pfd[npfd].fd = ifd;
        pfd[npfd].events = POLLIN;
        pfd[npfd].revents = 0;
        npfd++;
        if (!IS_N() && tty_fd != -1 && !child_running) {
            pfd[npfd].fd = tty_fd;
            pfd[npfd].events = POLLIN;
            pfd[npfd].revents = 0;
            npfd++;
        }
        timeout = 200;
        if (dir_settle_until) { int t = ms_until(dir_settle_until); if (t < timeout) timeout = t; }
        if (dir_pair_until)   { int t = ms_until(dir_pair_until);   if (t < timeout) timeout = t; }
        if (debounce_until)   { int t = ms_until(debounce_until);   if (t < timeout) timeout = t; }
        if (post_child_until) { int t = ms_until(post_child_until); if (t < timeout) timeout = t; }
        nready = poll(pfd, npfd, timeout);
        if (nready > 0) {
            if (pfd[0].revents & POLLIN) handle_inotify();
            if (npfd > 1 && (pfd[1].revents & POLLIN)) handle_tty();
        }
    }
}

/* -------------------------------------------------------------- main --- */

static void parse_restart_signal(const char *name)
{
    static const char *names[] = { "HUP", "INT", "QUIT", "TERM", "USR1", "USR2" };
    static const int nums[] = { SIGHUP, SIGINT, SIGQUIT, SIGTERM, SIGUSR1, SIGUSR2 };
    int i;
    if (strncmp(name, "SIG", 3) == 0) name += 3;
    for (i = 0; i < 3; i++) {
        if (strcmp(name, names[i]) == 0) {
            restart_sig = nums[i];
            return;
        }
    }
    fprintf(stderr, "%s: unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)\n", argv0, name);
    exit(1);
}

int main(int argc, char **argv)
{
    int ch, i, nutil;
    char **utility;
    char *env;

    argv0 = progname(argv[0]);
    trace = (getenv("EV_TRACE") != NULL);
    if (getenv("ENTR_INOTIFY_WORKAROUND") != NULL) {
        workaround = 1;
        fprintf(stderr, "%s: broken inotify workaround enabled\n", argv0);
    }
    follow_symlink = (getenv("ENTR_FOLLOW_SYMLINK") != NULL);

    if (argc > 1 && strcmp(argv[1], "-h") == 0) usage_summary();

    while ((ch = getopt(argc, argv, "acdnprsxz")) != -1) {
        switch (ch) {
        case 'a': options |= OPT_A; break;
        case 'c': clear_count++; options |= OPT_C; break;
        case 'd': d_count++; options |= OPT_D; break;
        case 'n': options |= OPT_N; break;
        case 'p': options |= OPT_P; break;
        case 'r': options |= OPT_R; break;
        case 's': options |= OPT_S; break;
        case 'x': x_count++; options |= OPT_X; break;
        case 'z': options |= OPT_Z; break;
        default: usage_short();
        }
    }
    argc -= optind;
    argv += optind;
    if (argc < 1) usage_short();

    if (IS_S() && argc != 1) {
        fprintf(stderr, "%s: -s requires commands to be formatted as a single argument\n", argv0);
        exit(1);
    }
    if (IS_R() && IS_X()) {
        fprintf(stderr, "%s: -r and -x may not be combined\n", argv0);
        exit(1);
    }
    if ((env = getenv("ENTR_RESTART_SIGNAL")) != NULL) parse_restart_signal(env);

    utility = xmalloc((argc + 2) * sizeof(char *));
    for (i = 0; i < argc; i++) utility[i] = argv[i];
    utility[argc] = NULL;
    nutil = argc;
    utility_name = progname(utility[0]);

    if ((ifd = inotify_init1(IN_NONBLOCK)) == -1) die("cannot initialize inotify");
    read_file_list();
    if (!has_regular()) {
        fprintf(stderr, "%s: No regular files to watch\n", argv0);
        if (IS_X()) setup_status();
        cleanup();
        exit(1);
    }
    for (i = 0; i < nwatch; i++) {
        if (add_watch(&watches[i]) < 0) {
            fprintf(stderr, "%s: failed to register VNODE event: %s\n", argv0, strerror(errno));
            cleanup();
            exit(1);
        }
    }
    if (trace) fprintf(stderr, "open_max: %ld\n", sysconf(_SC_OPEN_MAX));
    if (IS_X()) setup_status();
    if (getenv("PAGER") == NULL) setenv("PAGER", "cat", 0);
    if (!IS_N()) setup_tty();

    for (i = 0; i < nwatch; i++) {
        if (watches[i].type == F_FILE) {
            char buf[PATH_MAX + 2];
            if (realpath(watches[i].path, buf) != NULL) trigger_path = xstrdup(buf);
            break;
        }
    }
    g_utility = utility;
    g_nutility = nutil;

    signal(SIGINT, on_sigint);
    signal(SIGTERM, SIG_IGN);
    signal(SIGHUP, SIG_IGN);
    signal(SIGPIPE, SIG_IGN);
    signal(SIGTTIN, SIG_IGN);
    signal(SIGTTOU, SIG_IGN);

    /* substitute /_ with the path of the file which triggered the event */
    {
        int j;
        for (j = 1; j < g_nutility; j++) {
            if (strcmp(g_utility[j], "/_") == 0) {
                g_utility[j] = (char *)(trigger_path ? trigger_path : "");
                break;
            }
        }
    }
    if (IS_S()) {
        /* the command is evaluated by $SHELL */
        char *shell = getenv("SHELL");
        if (shell == NULL || *shell == 0) shell = "/bin/sh";
        g_utility = xmalloc(5 * sizeof(char *));
        g_utility[0] = shell;
        g_utility[1] = "-c";
        g_utility[2] = utility[0];
        g_utility[3] = (char *)(trigger_path ? trigger_path : "");
        g_utility[4] = NULL;
        g_nutility = 4;
        utility_name = progname(shell);
    }

    main_loop();
    cleanup();
    return 0;
}
